/**
 * Browse the active bicycle template catalog with optional search filtering.
 *
 * Search matches on `brand` or `model` (case-insensitive partial match).
 * Returns only active templates.
 */
export async function browseTemplates(search?: string): Promise<TemplatesCatalogResponse> {
  const [results, total] = await Promise.all([
    listTemplates(search),
    countTemplates(search)
  ])

  return {
    templates: results.map(toCatalogItem),
    total
  }
}

